import { Injectable, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { PILOT_TERRITORY } from '../../../core/catalog/pilot-territory';
import {
  BoundaryCollection,
  BoundaryMetadata,
  DepartmentProperties,
  MunicipalityProperties,
  MunicipalitySummary,
} from '../models/geo.models';
import { displayName, geometryBBox } from '../utils/geo-utils';

/**
 * Loads the static DANE MGN boundary files (generated by the pipeline) and
 * caches them for the session. Municipal boundaries are only requested when
 * needed (zooming into or selecting within the pilot department).
 */
@Injectable({ providedIn: 'root' })
export class GeoBoundariesService {
  private readonly http = inject(HttpClient);
  private readonly files = PILOT_TERRITORY.boundaries;

  private departmentsCache?: Promise<BoundaryCollection<DepartmentProperties>>;
  private municipalitiesCache?: Promise<BoundaryCollection<MunicipalityProperties>>;
  private metadataCache?: Promise<BoundaryMetadata>;

  departments(): Promise<BoundaryCollection<DepartmentProperties>> {
    return (this.departmentsCache ??= this.load(this.files.departments, () => {
      this.departmentsCache = undefined;
    }));
  }

  municipalities(): Promise<BoundaryCollection<MunicipalityProperties>> {
    return (this.municipalitiesCache ??= this.load(this.files.municipalities, () => {
      this.municipalitiesCache = undefined;
    }));
  }

  metadata(): Promise<BoundaryMetadata> {
    return (this.metadataCache ??= this.load(this.files.metadata, () => {
      this.metadataCache = undefined;
    }));
  }

  /** Sorted, display-ready list of municipalities (used by the accessible selector). */
  async municipalitySummaries(): Promise<MunicipalitySummary[]> {
    const fc = await this.municipalities();
    return fc.features
      .map((f) => ({
        id: f.id,
        code: f.properties.code,
        name: displayName(f.properties.name),
        areaKm2: f.properties.areaKm2,
        bbox: geometryBBox(f.geometry),
      }))
      .sort((a, b) => a.name.localeCompare(b.name, 'es'));
  }

  /** Sorted list of Colombian departments (for geographic search). */
  async departmentSummaries(): Promise<{ code: string; name: string }[]> {
    const fc = await this.departments();
    return fc.features
      .map((f) => ({ code: f.properties.code, name: displayName(f.properties.name) }))
      .sort((a, b) => a.name.localeCompare(b.name, 'es'));
  }

  /** One municipality's boundary (for the plot map), or null if unknown. */
  async municipality(code: string) {
    const fc = await this.municipalities();
    return fc.features.find((f) => f.properties.code === code) ?? null;
  }

  /** Failed requests are not cached, so the user can retry. */
  private load<T>(path: string, onError: () => void): Promise<T> {
    return firstValueFrom(this.http.get<T>(path)).catch((err) => {
      onError();
      throw err;
    });
  }
}
